#include "fir.h"

// Optimized FIR filter for Alveo U55C @ 200 MHz
// Uses circular buffer to reduce memory footprint and enable pipelining
void fir(const DataT in[LEN], DataT out[LEN]) {
    // Memory interfaces for Alveo DDR/HBM
    #pragma HLS INTERFACE m_axi port=in offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=out offset=slave bundle=gmem1
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local circular buffer for last TAPS samples (smaller than full LEN)
    DataT window[TAPS];
    #pragma HLS ARRAY_PARTITION variable=window complete dim=1

    int write_ptr = 0;

    for (int i = 0; i < LEN; i++) {
        #pragma HLS PIPELINE II=1

        // Store new sample in circular buffer
        window[write_ptr] = in[i];

        // Compute FIR output using window contents
        DataT acc = 0;
        for (int j = 0; j < TAPS; j++) {
            #pragma HLS UNROLL

            // Calculate buffer index (circular wrap-around)
            int buf_idx = write_ptr - j;
            if (buf_idx < 0) buf_idx += TAPS;

            // Zero history: only accumulate valid samples (i >= j)
            if (i >= j) {
                acc += window[buf_idx] * COEFFS[j];
            }
        }
        out[i] = acc;

        // Advance write pointer for next iteration
        write_ptr++;
        if (write_ptr == TAPS) write_ptr = 0;
    }
}
